14	/// Lexically clean a candidate path: strip a leading `./`, drop `.` components,
15	/// and collapse `..` without touching the filesystem. A leading `..` that
16	/// escapes the root survives (so it will not match an anchored pattern).
17	pub(crate) fn clean_path(path: &str) -> String {
18	    let trimmed = path.strip_prefix("./").unwrap_or(path);
19	    let mut out: Vec<&str> = Vec::new();
20	    for comp in trimmed.split('/') {
21	        match comp {
22	            "" | "." => {}
23	            ".." => {
24	                if out.last().is_some_and(|c| *c != "..") {
25	                    out.pop();
26	                } else {
27	                    out.push("..");
28	                }
29	            }
30	            other => out.push(other),
31	        }
32	    }
33	    out.join("/")
34	}
