37	/// any `.git` or `.ssh` path component, or a final component equal to `.env`
38	/// or beginning `.env.` (e.g. `.env.local`). Component equality — never a
39	/// substring — so `name.git/`, `.gitignore`, and `environment.env` do not trip.
40	/// Comparison is case-insensitive (so `.SSH/` / `.ENV` cannot bypass the
41	/// breaker on case-insensitive filesystems), matching [`PathGlob`].
42	pub(crate) fn is_protected_dotpath(path: &str) -> bool {
43	    let cleaned = clean_path(path);
