100	/// Trim a leading `./` then a single leading `/` (gitignore anchor — we anchor
101	/// instead by the presence of an interior `/`).
102	fn normalize_pattern(pat: String) -> String {
103	    let p = pat.strip_prefix("./").unwrap_or(&pat);
