108	/// Build a case-insensitive `GlobSet`. A pattern with no `/` is unanchored
109	/// (matches at any depth) → `{pat, **/pat}`; a pattern with a `/` is anchored.
110	fn build_globset(pattern: &str) -> GlobSet {
111	    let globs: Vec<String> = if pattern.contains('/') {
112	        vec![pattern.to_owned()]
113	    } else {
114	        vec![pattern.to_owned(), format!("**/{pattern}")]
115	    };
116	    let mut builder = GlobSetBuilder::new();
117	    for g in globs {
118	        if let Ok(glob) = GlobBuilder::new(&g)
119	            .case_insensitive(true)
120	            .literal_separator(true)
121	            .build()
122	        {
123	            builder.add(glob);
124	        }
125	    }
126	    builder.build().unwrap_or_else(|_| GlobSet::empty())
127	}
