    // Plan's read-only restriction. This is intentional (global pre-approval).
    let c = ctx()
        .with_permission_mode(PermissionMode::Plan)
        .with_allow_rules(vec![AllowRule::tool("Write")]);
    let i = interceptors(&c);
    assert!(matches!(
        i.authorize("Write", ToolEffect::Write, &json!({"path": "a"})).await,
        PermissionDecision::Allow
    ));
}
```

