            Ok(glob) => {
                builder.add(glob);
            }
            Err(e) => {
                debug_assert!(false, "invalid path-rule glob `{g}`: {e}");
                tracing::warn!(glob = %g, error = %e, "invalid path-rule glob; this rule will not match");
