        assert!(!is_protected_dotpath("name.git/config")); // bare repo
        assert!(!is_protected_dotpath(".gitignore"));
        assert!(!is_protected_dotpath("environment.env"));
        assert!(!is_protected_dotpath("src/main.rs"));
    }
}

